def tf_GradientTape_inputs():
    list_of_inputs = []

    # Input 1
    input_dict = {
        "persistent": False,
        "watch_accessed_variables": True
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 2
    input_dict = {
        "persistent": True,
        "watch_accessed_variables": False
    }
