def tf_linalg_solve_inputs():
    list_of_inputs = []

    # Input 1: Basic case with float32
    matrix = np.array([[1.0, 2.0], [3.0, 4.0]], dtype=np.float32)
    rhs = np.array([[5.0], [6.0]], dtype=np.float32)
