def tf_nn_sigmoid_cross_entropy_with_logits_inputs():
    list_of_inputs = []

    # Input 1: Basic example
    labels = np.array([0.0, 1.0, 0.5], dtype=np.float32)
    logits = np.array([1.0, -1.0, 0.0], dtype=np.float32)
    name = None
    input_dict = {"labels": labels, "logits": logits, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 2: Different values
    labels = np.array([0.2, 0.8, 0.1, 0.9], dtype=np.float32)
    logits = np.array([-2.0, 2.0, -0.5, 0.5], dtype=np.float32)
    name = "example2"
    input_dict = {"labels": labels, "logits": logits, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 3: Zero labels
    labels = np.array([0.0, 0.0, 0.0], dtype=np.float32)
    logits = np.array([1.0, -1.0, 0.0], dtype=np.float32)
    name = "example3"
    input_dict = {"labels": labels, "logits": logits, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 4: One labels
    labels = np.array([1.0, 1.0, 1.0], dtype=np.float32)
    logits = np.array([1.0, -1.0, 0.0], dtype=np.float32)
    name = "example4"
    input_dict = {"labels": labels, "logits": logits, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 5: Negative logits
    labels = np.array([0.0, 1.0, 0.5], dtype=np.float32)
    logits = np.array([-1.0, -2.0, -0.5], dtype=np.float32)
    name = "example5"
    input_dict = {"labels": labels, "logits": logits, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 6: Positive logits
    labels = np.array([0.0, 1.0, 0.5], dtype=np.float32)
    logits = np.array([1.0, 2.0, 0.5], dtype=np.float32)
    name = "example6"
    input_dict = {"labels": labels, "logits": logits, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 7: 2D arrays
    labels = np.array([[0.0, 1.0], [0.5, 0.2]], dtype=np.float32)
    logits = np.array([[1.0, -1.0], [0.0, 2.0]], dtype=np.float32)
    name = "example7"
    input_dict = {"labels": labels, "logits": logits, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 8: 3D arrays
    labels = np.random.rand(2, 3, 4).astype(np.float32)
    logits = np.random.randn(2, 3, 4).astype(np.float32)
