    x2 = np.array(2.0, dtype=np.float32)
    input_dict = {"x1": x1, "x2": x2}
    list_of_inputs.append(copy.deepcopy(input_dict))

    x1 = np.array(2.0, dtype=np.float32)
    x2 = np.array(3.0, dtype=np.float32)
    input_dict = {"x1": x1, "x2": x2}
