    list_of_inputs.append(copy.deepcopy(input_dict))
    
    # Input 10: float32 with zero
    x = np.array([0.01, 0.1, 1.0, 0.0], dtype=np.float32)
    name = "reciprocal_10"
    input_dict = {"x": x, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))
    
    # Input 11: float64, scalar value
