    name = "transpose_4"
    input_dict = {"a": a, "perm": perm, "conjugate": conjugate, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 5: 1D array
    a = np.array([1, 2, 3, 4, 5])
    perm = [0]
    conjugate = False
    name = "transpose_5"
    input_dict = {"a": a, "perm": perm, "conjugate": conjugate, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))
    
    # Input 6: 4D array
