    diagonal_9 = np.array([10, 20], dtype=np.uint8)
    list_of_inputs.append({
        'name': 'uint8_rect_2d',
        'input': input_9,
        'diagonal': diagonal_9
    })

    # Case 10: 4D input, int32, 1x1 batch size
