import numpy as np
import copy

def tf_linalg_tridiagonal_matmul_inputs():
    list_of_inputs = []

    # Input 1: Basic float32, no batch
    diagonals = np.array([
        [1.0, 2.0, 0.0],  # superdiag
        [3.0, 4.0, 5.0],  # maindiag
        [0.0, 6.0, 7.0]   # subdiag
    ], dtype=np.float32)
    rhs = np.array([
        [1.0, 1.0],
        [2.0, 2.0],
        [3.0, 3.0]
    ], dtype=np.float32)
    input_dict = {
        'diagonals': diagonals,
        'rhs': rhs,
        'diagonals_format': 'compact',
        'name': 'matmul_1'
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 2: float64, with negative values
    diagonals = np.array([
        [-1.0, -2.0, 0.0, 0.0],
        [2.0, 2.0, -2.0, 2.0],
        [0.0, -1.0, -1.0, -3.0]
    ], dtype=np.float64)
    rhs = np.array([
        [1.0],
        [-1.0],
        [2.0],
        [-2.0]
    ], dtype=np.float64)
