import numpy as np
import tensorflow as tf
import copy

def tf_raw_ops_BatchMatMulV2_inputs():
    list_of_inputs = []

    # Input 1: Basic 2D float32 matmul
    x = np.random.randn(2, 3).astype(np.float32)
    y = np.random.randn(3, 4).astype(np.float32)
    input_dict = {
        'adj_x': False,
        'adj_y': False,
        'grad_x': False,
        'grad_y': False,
        'name': "matmul_1",
        'x': x,
        'y': y
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 2: Transposing x with float64
    x = np.random.randn(3, 2).astype(np.float64)
    y = np.random.randn(3, 4).astype(np.float64)
    input_dict = {
        'adj_x': True,
        'adj_y': False,
        'grad_x': False,
        'grad_y': False,
        'name': "matmul_2",
        'x': x,
        'y': y
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 3: Transposing y with int32
    x = np.random.randint(-10, 10, size=(2, 3)).astype(np.int32)
    y = np.random.randint(-10, 10, size=(4, 3)).astype(np.int32)
    input_dict = {
        'adj_x': False,
        'adj_y': True,
        'grad_x': False,
        'grad_y': False,
        'name': "matmul_3",
        'x': x,
        'y': y
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 4: 3D batched matmul, grad_x enabled
    x = np.random.randn(2, 2, 3).astype(np.float32)
    y = np.random.randn(2, 3, 4).astype(np.float32)
    input_dict = {
        'adj_x': False,
        'adj_y': False,
        'grad_x': True,
        'grad_y': False,
        'name': "matmul_4",
        'x': x,
        'y': y
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 5: Complex64 with adjoints on both
    x = (np.random.randn(2, 3, 2) + 1j * np.random.randn(2, 3, 2)).astype(np.complex64)
    y = (np.random.randn(2, 4, 3) + 1j * np.random.randn(2, 4, 3)).astype(np.complex64)
    input_dict = {
        'adj_x': True,
        'adj_y': True,
        'grad_x': False,
        'grad_y': False,
        'name': "matmul_5",
        'x': x,
        'y': y
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 6: Broadcasting batch dimensions (4D)
    x = np.random.randn(1, 3, 2, 4).astype(np.float32)
    y = np.random.randn(2, 1, 4, 5).astype(np.float32)
    input_dict = {
        'adj_x': False,
        'adj_y': False,
        'grad_x': False,
        'grad_y': False,
        'name': "matmul_6",
        'x': x,
        'y': y
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 7: Large values, int64 data type
    x = np.random.randint(-100, 100, size=(5, 5)).astype(np.int64)
    y = np.random.randint(-100, 100, size=(5, 5)).astype(np.int64)
    input_dict = {
        'adj_x': False,
        'adj_y': False,
        'grad_x': False,
        'grad_y': False,
        'name': "matmul_7",
        'x': x,
        'y': y
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 8: 3D float32 with grad_x and grad_y enabled
    x = np.random.randn(1, 5, 2).astype(np.float32)
    y = np.random.randn(1, 5, 2).astype(np.float32)
    input_dict = {
        'adj_x': True,
        'adj_y': False,
        'grad_x': True,
        'grad_y': True,
        'name': "matmul_8",
        'x': x,
        'y': y
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 9: Highly nested 5D tensors with broadcasting
    x = np.random.randn(2, 1, 3, 2, 3).astype(np.float32)
    y = np.random.randn(1, 2, 3, 3, 4).astype(np.float32)
    input_dict = {
        'adj_x': False,
        'adj_y': False,
        'grad_x': False,
        'grad_y': False,
        'name': "matmul_9",
        'x': x,
        'y': y
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 10: Simple float16 matmul
    x = np.random.randn(4, 4).astype(np.float16)
    y = np.random.randn(4, 4).astype(np.float16)
    input_dict = {
        'adj_x': False,
        'adj_y': False,
        'grad_x': True,
        'grad_y': True,
        'name': "matmul_10",
        'x': x,
        'y': y
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    return list_of_inputs

generated_inputs["tf.raw_ops.BatchMatMulV2"] = generated_inputs.get("tf.raw_ops.BatchMatMulV2", []) + (tf_raw_ops_BatchMatMulV2_inputs())

import tensorflow as tf
import numpy as np
import copy

def tf_linalg_eigh_inputs():
    list_of_inputs = []

    # Input 1: 2x2 matrix, float32, positive values
    tensor_1 = np.array([[2.0, 1.0], [1.0, 2.0]], dtype=np.float32)
    input_dict_1 = {
        "tensor": tensor_1,
        "name": "eigh_float32_basic"
    }
    list_of_inputs.append(copy.deepcopy(input_dict_1))

    # Input 2: 2x2 matrix, float64, negative and positive values
    tensor_2 = np.array([[-5.0, 3.0], [3.0, -2.0]], dtype=np.float64)
    input_dict_2 = {
        "tensor": tensor_2,
        "name": "eigh_float64_neg"
    }
    list_of_inputs.append(copy.deepcopy(input_dict_2))

    # Input 3: 2x2 complex matrix, complex64
    tensor_3 = np.array([[1.0, 2.0 - 1.0j], [2.0 + 1.0j, 3.0]], dtype=np.complex64)
    input_dict_3 = {
        "tensor": tensor_3,
        "name": "eigh_complex64"
    }
    list_of_inputs.append(copy.deepcopy(input_dict_3))

    # Input 4: 3D batch of 2x2 matrices (shape: 2, 2, 2), float32
    tensor_4 = np.array([[[1.0, 0.0], [0.0, 1.0]], [[2.0, 1.0], [1.0, 3.0]]], dtype=np.float32)
    input_dict_4 = {
        "tensor": tensor_4,
        "name": "eigh_batch_3d"
    }
    list_of_inputs.append(copy.deepcopy(input_dict_4))

    # Input 5: 4x4 Identity matrix, float32
    tensor_5 = np.eye(4, dtype=np.float32)
    input_dict_5 = {
        "tensor": tensor_5,
        "name": "eigh_identity"
    }
    list_of_inputs.append(copy.deepcopy(input_dict_5))

    # Input 6: 4D batch of symmetric matrices (shape: 2, 2, 3, 3), float64
    raw_tensor_6 = np.random.randn(2, 2, 3, 3).astype(np.float64)
    tensor_6 = (raw_tensor_6 + np.swapaxes(raw_tensor_6, -1, -2)) / 2.0
    input_dict_6 = {
        "tensor": tensor_6,
        "name": "eigh_batch_4d"
    }
    list_of_inputs.append(copy.deepcopy(input_dict_6))

    # Input 7: 1x1 matrix (edge case), float32
    tensor_7 = np.array([[42.0]], dtype=np.float32)
    input_dict_7 = {
        "tensor": tensor_7,
        "name": "eigh_1x1"
    }
    list_of_inputs.append(copy.deepcopy(input_dict_7))

    # Input 8: 3D batch of complex matrices (shape: 2, 3, 3), complex128
    raw_tensor_8 = np.random.randn(2, 3, 3).astype(np.complex128) + 1j * np.random.randn(2, 3, 3).astype(np.complex128)
    tensor_8 = (raw_tensor_8 + np.swapaxes(raw_tensor_8, -1, -2).conj()) / 2.0
    input_dict_8 = {
        "tensor": tensor_8,
        "name": "eigh_complex128_batch"
    }
    list_of_inputs.append(copy.deepcopy(input_dict_8))

    # Input 9: 5x5 zero matrix, float32
    tensor_9 = np.zeros((5, 5), dtype=np.float32)
    input_dict_9 = {
        "tensor": tensor_9,
        "name": "eigh_zeros"
    }
    list_of_inputs.append(copy.deepcopy(input_dict_9))

    # Input 10: 2x2 symmetric matrix with extreme scaling, float64
    tensor_10 = np.array([[1e10, 1.0], [1.0, 1e-10]], dtype=np.float64)
    input_dict_10 = {
        "tensor": tensor_10,
        "name": "eigh_extreme_values"
    }
    list_of_inputs.append(copy.deepcopy(input_dict_10))

    return list_of_inputs

generated_inputs["tf.linalg.eigh"] = generated_inputs.get("tf.linalg.eigh", []) + (tf_linalg_eigh_inputs())

