import tensorflow as tf
import numpy as np
import copy
import sys

# Advanced monkeypatching of sys.modules to intercept 'get_ll' whenever it's loaded
class MonkeyPatchDict(dict):
    def _patch(self, value):
        if value is not None:
            try:
                if hasattr(value, 'get_ll'):
                    old_get_ll = getattr(value, 'get_ll')
                    if not getattr(old_get_ll, '_is_patched', False):
                        def new_get_ll(domain, val):
                            if domain == 'int':
                                return val
                            return old_get_ll(domain, val)
                        new_get_ll._is_patched = True
                        setattr(value, 'get_ll', new_get_ll)
            except Exception:
                pass
        return value

    def __setitem__(self, key, value):
        super().__setitem__(key, self._patch(value))

    def setdefault(self, key, default=None):
        return super().setdefault(key, self._patch(default))

    def update(self, *args, **kwargs):
        for k, v in dict(*args, **kwargs).items():
            self[k] = v

# Install the proxy sys.modules
sys.modules = MonkeyPatchDict(sys.modules)

# Trigger patch on already loaded modules
for k, v in list(sys.modules.items()):
    sys.modules[k] = v

