    dy = np.array(-0.5, dtype=np.float32)
    input_dict = {
        "name": "scalar_float32",
        "y": y,
        "dy": dy
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 7: float32, 4D array
