    dy = np.ones((2, 2, 2, 2), dtype=np.float32) * 0.1
    input_dict = {
        "name": "float32_4d",
        "y": y,
        "dy": dy
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 8: float64, 1D array
    y = np.array([-10.0, -1.0, 1.0, 10.0], dtype=np.float64)
    dy = np.array([0.01, 0.1, 1.0, 10.0], dtype=np.float64)
    input_dict = {
        "name": "float64_1d_large",
        "y": y,
        "dy": dy
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 9: float16, 2D array (3x1)
    y = np.array([[1.0], [2.0], [3.0]], dtype=np.float16)
    dy = np.array([[0.1], [0.2], [0.3]], dtype=np.float16)
    input_dict = {
        "name": "half_3x1",
        "y": y,
        "dy": dy
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

