import io
import wave
import numpy as np
import copy
import tensorflow as tf

def make_wav_bytes(num_channels=1, num_samples=100, sample_rate=16000):
    wav_io = io.BytesIO()
    with wave.open(wav_io, 'wb') as wav_file:
        wav_file.setnchannels(num_channels)
        wav_file.setsampwidth(2) # 16-bit PCM
        wav_file.setframerate(sample_rate)
        data = np.random.randint(-1000, 1000, size=(num_samples, num_channels), dtype=np.int16)
        wav_file.writeframes(data.tobytes())
    return wav_io.getvalue()

def tf_audio_decode_wav_inputs():
    list_of_inputs = []

    # Input 1: Standard mono WAV, default params
    input_dict = {
        "contents": np.array(make_wav_bytes(1, 100, 16000), dtype=object),
        "desired_channels": np.int32(-1),
        "desired_samples": np.int32(-1),
        "name": "decode_1"
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 2: Stereo WAV, default params
    input_dict = {
        "contents": np.array(make_wav_bytes(2, 100, 16000), dtype=object),
        "desired_channels": np.int32(-1),
        "desired_samples": np.int32(-1),
        "name": "decode_2"
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 3: Mono WAV, duplicate channels to 2
    input_dict = {
        "contents": np.array(make_wav_bytes(1, 100, 16000), dtype=object),
        "desired_channels": np.int32(2),
        "desired_samples": np.int32(-1),
        "name": "decode_3"
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 4: Stereo WAV, reduce channels to 1
    input_dict = {
        "contents": np.array(make_wav_bytes(2, 100, 16000), dtype=object),
        "desired_channels": np.int32(1),
        "desired_samples": np.int32(-1),
        "name": "decode_4"
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 5: Mono WAV, crop samples to 50
    input_dict = {
        "contents": np.array(make_wav_bytes(1, 100, 16000), dtype=object),
        "desired_channels": np.int32(-1),
        "desired_samples": np.int32(50),
        "name": "decode_5"
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 6: Mono WAV, pad samples to 200
    input_dict = {
        "contents": np.array(make_wav_bytes(1, 100, 16000), dtype=object),
        "desired_channels": np.int32(-1),
        "desired_samples": np.int32(200),
        "name": "decode_6"
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 7: Stereo WAV, desired channels and samples specified
    input_dict = {
        "contents": np.array(make_wav_bytes(2, 120, 22050), dtype=object),
        "desired_channels": np.int32(2),
        "desired_samples": np.int32(150),
        "name": "decode_7"
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 8: 4-channel WAV, drop to 2 channels, crop samples
    input_dict = {
        "contents": np.array(make_wav_bytes(4, 80, 44100), dtype=object),
        "desired_channels": np.int32(2),
        "desired_samples": np.int32(50),
        "name": "decode_8"
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 9: Low sample rate mono WAV
    input_dict = {
        "contents": np.array(make_wav_bytes(1, 60, 8000), dtype=object),
        "desired_channels": np.int32(-1),
        "desired_samples": np.int32(60),
        "name": "decode_9"
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 10: 3-channel WAV, duplicate to 4 channels, pad samples
    input_dict = {
        "contents": np.array(make_wav_bytes(3, 150, 48000), dtype=object),
        "desired_channels": np.int32(4),
        "desired_samples": np.int32(200),
        "name": "decode_10"
    }
    list_of_inputs.append(copy.deepcopy(input_dict))

    return list_of_inputs

