class SafeList(list):
    def __array__(self, dtype=None, copy=None):
        return np.array(list(self), dtype=object)

def tf_data_experimental_make_csv_dataset_inputs():
    list_of_inputs = []

    # Prepare temp CSV files with homogeneous column types
    # 1. All Float CSV
    f1 = tempfile.NamedTemporaryFile(mode='w+', suffix='.csv', delete=False)
    f1.write("col_a,col_b\n1.0,10.0\n2.0,20.0\n")
    f1.close()

    # 2. All Float TSV
    f2 = tempfile.NamedTemporaryFile(mode='w+', suffix='.tsv', delete=False)
    f2.write("col_a\tcol_b\n1.0\t10.0\n2.0\t20.0\n")
    f2.close()

    # 3. All Int CSV (No header)
    f3 = tempfile.NamedTemporaryFile(mode='w+', suffix='.csv', delete=False)
    f3.write("1,10\n2,20\n")
    f3.close()

    # 4. All Float GZIP CSV
    f4 = tempfile.NamedTemporaryFile(suffix='.csv.gz', delete=False)
    with gzip.open(f4.name, 'wt') as f:
        f.write("col_a,col_b\n1.0,10.0\n2.0,20.0\n")
    f4.close()

    # 5. All String CSV with NA
    f5 = tempfile.NamedTemporaryFile(mode='w+', suffix='.csv', delete=False)
    f5.write("col_a,col_b\ncat,?\n?,dog\n")
    f5.close()

    # 6. All String CSV with quotes
    f6 = tempfile.NamedTemporaryFile(mode='w+', suffix='.csv', delete=False)
    f6.write("col_a,col_b\n\"apple\",\"banana\"\n\"cherry\",\"date\"\n")
