import numpy as np
import tensorflow as tf
import copy

def tf_expand_dims_inputs():
    list_of_inputs = []
    
    # Input 1: 1D float array, axis 0
    list_of_inputs.append({
        "input": np.array([1.0, 2.0, 3.0], dtype=np.float32),
        "axis": 0,
        "name": "expand_axis_0"
    })
    
    # Input 2: 1D float array, axis -1 (innermost)
    list_of_inputs.append({
        "input": np.array([4.0, 5.0, 6.0], dtype=np.float32),
        "axis": -1,
        "name": "expand_axis_neg1"
    })

    # Input 3: 2D int array, axis 1
    list_of_inputs.append({
        "input": np.array([[1, 2], [3, 4]], dtype=np.int32),
        "axis": 1,
        "name": "expand_axis_1"
    })

    # Input 4: 2D int array, axis -3 (outermost)
    list_of_inputs.append({
        "input": np.array([[5, 6], [7, 8]], dtype=np.int32),
        "axis": -3,
        "name": "expand_axis_neg3"
    })

    # Input 5: Scalar (0D), axis 0
    list_of_inputs.append({
        "input": np.array(42, dtype=np.int32),
        "axis": 0,
        "name": "expand_scalar_0"
    })

    # Input 6: Scalar (0D), axis -1
    list_of_inputs.append({
        "input": np.array(3.14, dtype=np.float64),
        "axis": -1,
        "name": "expand_scalar_neg1"
    })

    # Input 7: 3D bool array, axis 2
    list_of_inputs.append({
        "input": np.array([[[True, False], [False, True]], [[True, True], [False, False]]], dtype=np.bool_),
        "axis": 2,
        "name": "expand_3d_bool"
    })

    # Input 8: 3D float array, axis -4 (outermost for 3D)
    list_of_inputs.append({
        "input": np.ones((2, 3, 4), dtype=np.float32),
        "axis": -4,
        "name": "expand_3d_neg4"
    })

    # Input 9: 4D int array, axis 3
    list_of_inputs.append({
        "input": np.zeros((1, 2, 2, 1), dtype=np.int32),
        "axis": 3,
        "name": "expand_4d_3"
    })

